                back=(lambda k, x, y, z0, r, rng: [_tree(k, x, y, z0, rng.uniform(0.14, 0.2), B_GIRDER, trunk=B_SOOT)], (0.06, 0.09)),
                tower=lambda k, x, y, z0, h, rng: chs_tower(k, x, y, z0, h * 1.4, 0.04, rng.uniform(0, TAU)),
